insert into CHB_FINANCE_PRODUCTS_SUB ( REGIST_SEQNO,STATUS_BATCH,PROD_ID, PROD_NAME, SURFACE_IN_OUT, PROD_BRAND, PROD_STAGE, RAISE_CCY, RAISE_AMT_PLAN, TOTAL_AMT, SALE_AMT_STR, RAISE_VDATE, RAISE_ENDDATE, CASH_PRIN_CCY, CASH_PROF_CCY, VDATE, MDATE, LOW_YIELD, HIGH_YIELD, IS_CONSTRACTE, RISK_LEVEL, PROD_MANAGE_PATTERN, CONT_MODE, PROFIT_TYPE, PROD_SALEBANK_NAME, OPERATE_MODE, CMMODE, TERM_RIGHT_FLAG, COOPERATION_NAME, INV_ASSET_TYPE, CUSTOMER_RISK_LEVEL, CUSTOMER_TYPE, INVEST_ARAE, REMARK, BANK_MARK, DATE_STATUS, GROUP_ID, STATUS, CREATE_USER, ORG_CODE, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME ) select A.* from (
select #{item.registSeqno,jdbcType=VARCHAR} AS REGIST_SEQNO, #{item.statusBatch,jdbcType=VARCHAR} AS STATUS_BATCH, #{item.prodId,jdbcType=VARCHAR} AS PROD_ID, #{item.prodName,jdbcType=VARCHAR} AS PROD_NAME, #{item.surfaceInOut,jdbcType=VARCHAR} AS SURFACE_IN_OUT, #{item.prodBrand,jdbcType=VARCHAR} AS PROD_BRAND, #{item.prodStage,jdbcType=VARCHAR} AS PROD_STAGE, #{item.raiseCcy,jdbcType=VARCHAR} AS RAISE_CCY, #{item.raiseAmtPlan,jdbcType=DECIMAL} AS RAISE_AMT_PLAN, #{item.totalAmt,jdbcType=DECIMAL} AS TOTAL_AMT, #{item.saleAmtStr,jdbcType=DECIMAL} AS SALE_AMT_STR, #{item.raiseVdate,jdbcType=DATE} AS RAISE_VDATE, #{item.raiseEnddate,jdbcType=DATE} AS RAISE_ENDDATE, #{item.cashPrinCcy,jdbcType=VARCHAR} AS CASH_PRIN_CCY, #{item.cashProfCcy,jdbcType=VARCHAR} AS CASH_PROF_CCY, #{item.vdate,jdbcType=DATE} AS VDATE, #{item.mdate,jdbcType=DATE} AS MDATE, #{item.lowYield,jdbcType=DECIMAL} AS LOW_YIELD, #{item.highYield,jdbcType=DECIMAL} AS HIGH_YIELD, #{item.isConstracte,jdbcType=VARCHAR} AS IS_CONSTRACTE, #{item.riskLevel,jdbcType=VARCHAR} AS RISK_LEVEL, #{item.prodManagePattern,jdbcType=VARCHAR} AS PROD_MANAGE_PATTERN, #{item.contMode,jdbcType=VARCHAR} AS CONT_MODE, #{item.profitType,jdbcType=VARCHAR} AS PROFIT_TYPE, #{item.prodSalebankName,jdbcType=VARCHAR} AS PROD_SALEBANK_NAME, #{item.operateMode,jdbcType=VARCHAR} AS OPERATE_MODE, #{item.cmmode,jdbcType=VARCHAR} AS CMMODE, #{item.termRightFlag,jdbcType=VARCHAR} AS TERM_RIGHT_FLAG, #{item.cooperationName,jdbcType=VARCHAR} AS COOPERATION_NAME, #{item.invAssetType,jdbcType=VARCHAR} AS INV_ASSET_TYPE, #{item.customerRiskLevel,jdbcType=VARCHAR} AS CUSTOMER_RISK_LEVEL, #{item.customerType,jdbcType=VARCHAR} AS CUSTOMER_TYPE, #{item.investArae,jdbcType=VARCHAR} AS INVEST_ARAE, #{item.remark,jdbcType=VARCHAR} AS REMARK, #{item.bankMark,jdbcType=VARCHAR} AS BANK_MARK, #{item.dateStatus,jdbcType=DATE} AS DATE_STATUS, #{item.groupId,jdbcType=VARCHAR} AS GROUP_ID, #{item.status,jdbcType=VARCHAR} AS STATUS, #{item.createUser,jdbcType=VARCHAR} AS CREATE_USER, #{item.orgCode,jdbcType=VARCHAR} AS ORG_CODE, #{item.createDept,jdbcType=VARCHAR} AS CREATE_DEPT, #{item.createTime,jdbcType=TIMESTAMP} AS CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} AS UPDATE_USER, #{item.updateTime,jdbcType=TIMESTAMP} AS UPDATE_TIME from dual
) A
